-- Complete purchase request approval control with audited rejection.
create or replace function public.reject_purchase_request(p_request uuid,p_reason text)returns text language plpgsql security definer set search_path=public as $$declare v_status text;v_roles text[];begin select status into v_status from purchase_requests where purchase_request_id=p_request for update;if not found then raise exception'request not found';end if;if v_status not in('PENDING_CHECK','PENDING_PREAPPROVAL','PENDING_APPROVAL')then raise exception'request cannot be rejected from status %',v_status;end if;if nullif(trim(p_reason),'')is null then raise exception'rejection reason is required';end if;v_roles:=case v_status when'PENDING_CHECK'then array['admin','purchase']when'PENDING_PREAPPROVAL'then array['admin','production_manager']else array['admin']end;if not has_factory_role(auth.uid(),v_roles)then raise exception'not authorized to reject at this stage';end if;update purchase_requests set status='REJECTED',updated_at=now(),updated_by=auth.uid()::text where purchase_request_id=p_request;insert into audit_log(user_id,action,entity_type,entity_id,old_value,new_value,reason)values(auth.uid(),'Purchase Request Rejected','purchase_requests',p_request,jsonb_build_object('status',v_status),jsonb_build_object('status','REJECTED'),trim(p_reason));return'REJECTED';end$$;
revoke all on function public.reject_purchase_request(uuid,text)from public;grant execute on function public.reject_purchase_request(uuid,text)to authenticated;
